// ═══════════════════════════════════════════════════════════════════════════════
// FILL-IN PUZZLE (2026-11, nostalgia batch 2) — the "fill-ins" of newspaper puzzle pages and puzzle books: no clues,
// just a list of words and an empty grid. Fit every word in. Solo, no clock.
// The grid is generated by crossing words from the list below; one word is printed in as a starter. Tap a square
// (tap again to switch between across and down), then tap a word of the right length. A word that clashes with
// letters already in the grid is refused, with the reason. Any filling that uses every word once and agrees at every
// crossing is accepted. Easy: 6 words, normal 9, hard 12 (and longer words).
// ═══════════════════════════════════════════════════════════════════════════════
const _FI_WORDS = ('DINER RADIO PIANO JUKEBOX PICNIC PORCH TRAIN CANOE KITE MARBLE SODA MALT BOWL QUILT APRON TEAPOT BISCUIT PANTRY ' +
    'GARDEN TULIP DAISY ROSE MAPLE ACORN BARN TRACTOR HAYRIDE CIDER APPLE PEACH PECAN CHERRY MELON LEMON SUGAR BUTTER TOAST ' +
    'BACON WAFFLE PANCAKE SYRUP COFFEE KETTLE STOVE OVEN RECIPE LADLE SPOON FORK PLATE SAUCER NAPKIN CANDLE LANTERN ' +
    'POSTCARD STAMP LETTER PARCEL RIBBON BUTTON THREAD NEEDLE THIMBLE YARN SWEATER MITTEN SCARF BONNET SLIPPER ' +
    'PARADE BANNER TRUMPET DRUM BUGLE BANJO FIDDLE VIOLIN GUITAR RECORD MOVIE TICKET POPCORN SEESAW SWING SLIDE ' +
    'ROCKET PLANET COMET ORBIT ISLAND HARBOR ANCHOR SAILOR OCEAN BEACH SHELL PEBBLE RIVER BRIDGE TUNNEL CABOOSE ' +
    'WAGON SADDLE PONY FARMER RANCH CORRAL FENCE GATE CHIMNEY ATTIC CELLAR WINDOW CURTAIN CARPET SOFA PILLOW BLANKET ' +
    'CLOCK CALENDAR PENCIL ERASER CRAYON CHALK RULER SCHOOL BELL RECESS LOCKER DIPLOMA CAMERA PHOTO ALBUM ' +
    'BINGO CHECKERS DOMINO PUZZLE RIDDLE SECRET TREASURE PIRATE CASTLE DRAGON KNIGHT ROBIN SPARROW EAGLE OWL HEN EGG ' +
    'TEA JAM PIE BUN ICE OAK ELM SUN MOON STAR CAR BUS VAN CAP HAT BAG BOX MAP INK PEN CUP MUG POT PAN').split(' ');
function _fiBuild(nWords, maxLen, size) {
    const pool = shuffle(_FI_WORDS.filter((w) => w.length <= maxLen && w.length >= 3));
    for (let attempt = 0; attempt < 60; attempt++) {
        const g = Array.from({ length: size }, () => Array(size).fill('')), placed = [];
        const fits = (w, r, c, dr, dc) => {
            if (r < 0 || c < 0 || r + dr * (w.length - 1) >= size || c + dc * (w.length - 1) >= size) return -1;
            const br = r - dr, bc = c - dc, ar = r + dr * w.length, ac = c + dc * w.length;
            if (br >= 0 && bc >= 0 && g[br][bc]) return -1; if (ar < size && ac < size && g[ar][ac]) return -1;
            let cross = 0;
            for (let i = 0; i < w.length; i++) {
                const y = r + dr * i, x = c + dc * i, ch = g[y][x];
                if (ch) { if (ch !== w[i]) return -1; cross++; continue; }
                // no side-by-side contact with parallel words
                const sy1 = y + dc, sx1 = x + dr, sy2 = y - dc, sx2 = x - dr;
                if ((sy1 < size && sx1 < size && g[sy1][sx1]) || (sy2 >= 0 && sx2 >= 0 && g[sy2][sx2])) return -1;
            }
            return cross;
        };
        const put = (w, r, c, dr, dc) => { for (let i = 0; i < w.length; i++) g[r + dr * i][c + dc * i] = w[i]; placed.push({ w, r, c, dr, dc }); };
        const first = pool[attempt % pool.length]; if (first.length > size) continue;
        put(first, Math.floor(size / 2), Math.floor((size - first.length) / 2), 0, 1);
        for (const w of shuffle(pool.slice())) {
            if (placed.length >= nWords) break;
            if (placed.some((p) => p.w === w)) continue;
            const opts = [];
            for (const p of placed) for (let i = 0; i < p.w.length; i++) for (let j = 0; j < w.length; j++) {
                if (p.w[i] !== w[j]) continue;
                const dr = p.dr ? 0 : 1, dc = p.dr ? 1 : 0, r = p.r + p.dr * i - dr * j, c = p.c + p.dc * i - dc * j;
                const x = fits(w, r, c, dr, dc); if (x > 0) opts.push([x, r, c, dr, dc]);
            }
            if (opts.length) { opts.sort((a, b) => b[0] - a[0]); const o = opts[0]; put(w, o[1], o[2], o[3], o[4]); }
        }
        if (placed.length >= nWords) return { size, placed };
    }
    return null;
}
function initFillIn() {
    NK.start('fillin', {
        setup(gs, diff) {
            const cfg = diff === 'easy' ? [6, 6, 8] : diff === 'hard' ? [12, 8, 11] : [9, 7, 10];
            let P = null; while (!P) P = _fiBuild(...cfg);
            gs.P = P; gs.size = P.size;
            gs.slots = P.placed.map((p) => ({ r: p.r, c: p.c, dr: p.dr, dc: p.dc, L: p.w.length, w: null }));
            gs.words = P.placed.map((p) => p.w).sort((a, b) => a.length - b.length || a.localeCompare(b));
            const st = Math.floor(Math.random() * gs.slots.length); gs.slots[st].w = P.placed[st].w; gs.slots[st].given = true;
            gs.sel = gs.slots.findIndex((s) => !s.w); gs.over = false;
            gs.msg = `One word is printed in to start you off. Tap a square, then a word of the right length.`;
        },
        view: _fiView,
        keys: { KeyR: () => fiRemove() },
        rules: [
            'Every word in the list fits into the grid exactly once. There are no clues: it is all about lengths and crossing letters.',
            'One word is already printed in. Words that cross share a letter.',
            'Tap a square to pick the word space through it (tap again to switch between across and down). Only words of the right length can be chosen.',
            'Tap a word to write it in. If it clashes with a letter that is already there, it is refused and the reason is shown.',
            'To take a word back out, pick its space and press <b>Remove word</b>.',
            'Fill every space to finish. A good start: the longest words and the lengths that only one word has. No clock.'],
        css: `.fi-grid{display:grid;gap:2px;max-width:min(100%,30rem);margin:0 auto}
.fi-c{aspect-ratio:1;background:#fffdf5;border:2px solid #c9a46a;--nk-bw:2px;--nk-r:4px;font:900 clamp(.95rem,4.2vw,1.45rem)/1 Georgia,serif;color:#1d4ed8;display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer;min-width:0}
.fi-c.fi-g{color:#2b1b0d}.fi-c.fi-s{background:#fde68a;border-color:#b45309}
.fi-x{aspect-ratio:1}
.fi-list{display:flex;flex-direction:column;gap:6px;margin-top:12px}
.fi-len{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.fi-len>span{font-weight:800;color:#4a3420;min-width:5.5em}
.fi-list .gk-btn{min-height:48px;font-size:1.05rem;letter-spacing:.04em}
.fi-list .gk-btn.fi-used{text-decoration:line-through;opacity:.55}`,
    });
}
const _fiCells = (s) => Array.from({ length: s.L }, (_, i) => [s.r + s.dr * i, s.c + s.dc * i]);
function _fiGrid(gs) { const g = {}; gs.slots.forEach((s) => { if (s.w) _fiCells(s).forEach(([r, c], i) => (g[r + ',' + c] = s.w[i])); }); return g; }
function fiCell(r, c) {
    const gs = gameState.fillin; if (gs.over) return;
    const here = gs.slots.map((s, k) => (_fiCells(s).some(([y, x]) => y === r && x === c) ? k : -1)).filter((k) => k >= 0);
    if (!here.length) return;
    gs.sel = here.length > 1 && here.includes(gs.sel) ? here[(here.indexOf(gs.sel) + 1) % here.length] : here.find((k) => !gs.slots[k].w) ?? here[0];
    const s = gs.slots[gs.sel];
    gs.msg = `${s.dr ? 'Down' : 'Across'} space of ${s.L} letters${s.w ? ` (now ${s.w})` : ''}.${here.length > 1 ? ' Tap again to switch direction.' : ''}`;
    NK.render('fillin');
}
function fiWord(i) {
    const gs = gameState.fillin; if (gs.over || gs.sel < 0) return;
    const w = gs.words[i], s = gs.slots[gs.sel];
    if (s.given) { gs.msg = 'That word was printed in to start you off.'; return NK.render('fillin'); }
    if (w.length !== s.L) { gs.msg = `${w} has ${w.length} letters; this space has ${s.L}.`; return NK.render('fillin'); }
    const usedAt = gs.slots.findIndex((x) => x.w === w);   // every list word is different, so each is used once
    if (usedAt >= 0 && usedAt !== gs.sel) { gs.msg = gs.slots[usedAt].given ? `${w} is the starter word, already printed in.` : `${w} is already in the grid. Remove it from its space first.`; return NK.render('fillin'); }
    const old = s.w; s.w = null;
    const g = _fiGrid(gs), cells = _fiCells(s);
    const clash = cells.findIndex(([r, c], k) => g[r + ',' + c] && g[r + ',' + c] !== w[k]);
    if (clash >= 0) { s.w = old; gs.msg = `${w} does not fit: letter ${clash + 1} would have to be ${g[cells[clash].join(',')]}, not ${w[clash]}.`; if (typeof sfxWrong === 'function') sfxWrong(); return NK.render('fillin'); }
    s.w = w; if (typeof sfxFlip === 'function') sfxFlip();
    if (gs.slots.every((x) => x.w)) {
        gs.over = true; gs.msg = 'Every word is in and every crossing agrees. Done!'; NK.render('fillin');
        if (typeof sfxCorrect === 'function') sfxCorrect();
        return NK.finish('fillin', true, `All ${gs.slots.length} words fitted in!`);
    }
    gs.msg = `${w} is in.`;
    const nx = gs.slots.findIndex((x) => !x.w); if (nx >= 0) gs.sel = nx;
    NK.render('fillin');
}
function fiRemove() {
    const gs = gameState.fillin; if (gs.over || gs.sel < 0) return;
    const s = gs.slots[gs.sel]; if (!s.w) { gs.msg = 'This space is empty already.'; return NK.render('fillin'); }
    if (s.given) { gs.msg = 'The starter word stays.'; return NK.render('fillin'); }
    gs.msg = `${s.w} taken out.`; s.w = null; NK.render('fillin');
}
function fiNew() { initFillIn(); }
function _fiView(gs) {
    const n = gs.size, g = _fiGrid(gs), sel = gs.slots[gs.sel], selSet = new Set(sel ? _fiCells(sel).map((x) => x.join(',')) : []);
    const given = new Set(); gs.slots.forEach((s) => { if (s.given) _fiCells(s).forEach((x) => given.add(x.join(','))); });
    const used = new Set(gs.slots.map((s) => _fiCells(s).map((x) => x.join(','))).flat());
    // trim empty border rows/cols
    let r0 = n, c0 = n, r1 = 0, c1 = 0; used.forEach((k) => { const [r, c] = k.split(',').map(Number); r0 = Math.min(r0, r); c0 = Math.min(c0, c); r1 = Math.max(r1, r); c1 = Math.max(c1, c); });
    let cells = '';
    for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
        const k = r + ',' + c;
        if (!used.has(k)) { cells += '<span class="fi-x"></span>'; continue; }
        const first = !cells.includes('data-first');
        cells += `<button type="button" class="nk-cell fi-c${given.has(k) ? ' fi-g' : ''}${selSet.has(k) ? ' fi-s' : ''}" onclick="fiCell(${r},${c})" data-k="f${r}_${c}"${first ? ' data-first' : ''} aria-label="square${g[k] ? ' ' + g[k] : ' empty'}"${gs.over ? ' disabled' : ''}>${g[k] || ''}</button>`;
    }
    const inGrid = gs.slots.map((s) => s.w).filter(Boolean);
    const byLen = {}; gs.words.forEach((w, i) => (byLen[w.length] = byLen[w.length] || []).push(i));
    const list = Object.keys(byLen).map((L) => `<div class="fi-len"><span>${L} letters</span>${byLen[L].map((i) => { const w = gs.words[i], u = inGrid.includes(w); return NK.btn(w, `fiWord(${i})`, { k: 'w' + i, cls: u ? 'fi-used' : '', disabled: gs.over || !sel || +L !== sel.L }); }).join('')}</div>`).join('');
    return `<div class="nk-top"><span>Words in: <b>${inGrid.length}</b> of ${gs.slots.length}</span><span>${sel ? `Space: ${sel.dr ? 'down' : 'across'}, ${sel.L} letters` : ''}</span></div>
      <div class="fi-grid" style="grid-template-columns:repeat(${c1 - c0 + 1},1fr)">${cells}</div>
      ${NK.msg(gs.msg)}
      <div class="gk-btns">${NK.btn('Remove word', 'fiRemove()', { k: 'remove', disabled: gs.over || !sel || !sel.w || sel.given })}${NK.btn(NK.icon('rotate-ccw') + 'New puzzle', 'fiNew()', { k: 'restart' })}</div>
      <div class="fi-list" aria-label="word list">${list}</div>`;
}
